    <script>
        function switchBicImage(el, src) {
            var mainImg = document.getElementById('mainBicImg');
            if (mainImg) {
                mainImg.style.opacity = '0';
                setTimeout(function() {
                    mainImg.src = src;
                    mainImg.style.opacity = '1';
                }, 150);
            }
            var thumbs = document.querySelectorAll('.bic-thumb-item');
            thumbs.forEach(function(t) { t.classList.remove('active'); });
            if (el) { el.classList.add('active'); }
        }
    </script>



